const enc=new TextEncoder(),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function webUrl(value,label,required=false){if(!value?.trim()){if(required)throw Error('Nhập '+label+'.');return ''}let url;try{url=new URL(value.trim())}catch{throw Error(label+': nhập URL đầy đủ, bắt đầu bằng https:// hoặc http://.')}if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw Error(label+': chỉ dùng HTTP/HTTPS và không kèm tài khoản.');return url.href}
function campaign(data){const url=new URL(webUrl(data.url,'URL trang đích',true));for(const key of ['source','medium','campaign'])if(!data[key]?.trim())throw Error('Nhập đủ nguồn, phương tiện và tên chiến dịch.');for(const key of ['source','medium','campaign','term','content','id']){const value=data[key]?.trim();if(value)url.searchParams.set('utm_'+key,value);else url.searchParams.delete('utm_'+key)}return {text:url.href,summary:['URL chiến dịch đã được tạo.','Tham số có sẵn và phần # được giữ; các UTM cùng tên được thay thế.']}}
function meta(data){if(!data.title?.trim())throw Error('Nhập tiêu đề trang.');const url=webUrl(data.url,'URL chuẩn'),image=webUrl(data.image,'URL ảnh chia sẻ');const lines=['<meta charset="UTF-8">','<meta name="viewport" content="width=device-width, initial-scale=1.0">',`<title>${esc(data.title.trim())}</title>`];const tag=(kind,name,value)=>{if(value?.trim())lines.push(`<meta ${kind}="${name}" content="${esc(value.trim())}">`)};tag('name','description',data.description);tag('name','author',data.author);tag('name','robots',data.robots==='noindex'?'noindex, nofollow':'index, follow');if(url)lines.push(`<link rel="canonical" href="${esc(url)}">`);if(data.og){tag('property','og:type',data.type==='article'?'article':'website');tag('property','og:title',data.title);tag('property','og:description',data.description);tag('property','og:url',url);tag('property','og:image',image);tag('property','og:site_name',data.site);tag('property','og:locale',data.locale||'vi_VN')}if(data.twitter){tag('name','twitter:card',image?'summary_large_image':'summary');tag('name','twitter:title',data.title);tag('name','twitter:description',data.description);tag('name','twitter:image',image);tag('name','twitter:site',data.twitterSite)}return {text:lines.join('\n'),summary:[`${lines.length} thẻ HTML · chèn trong <head> của trang.`,`Tiêu đề: ${data.title.length} ký tự · Mô tả: ${(data.description||'').length} ký tự`,'Các thẻ không bảo đảm thứ hạng hoặc cách hiển thị trên mọi nền tảng.']}}
function b64Bytes(value){if(!/^[A-Za-z0-9_-]*$/.test(value)||value.length%4===1)throw Error('JWT chứa phần Base64URL chưa hợp lệ.');const raw=atob(value.replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(value.length/4)*4,'='));return Uint8Array.from(raw,c=>c.charCodeAt(0))}
function jwt(token,now=Date.now()/1000){const clean=token.trim().replace(/^Bearer\s+/i,'');if(clean.length>1000000)throw Error('Token quá lớn; giới hạn 1 MB.');const parts=clean.split('.');if(parts.length!==3||!parts[0]||!parts[1])throw Error('Nhập JWT gồm 3 phần header.payload.signature. JWE 5 phần chưa được hỗ trợ.');let header,payload;try{const dec=new TextDecoder('utf-8',{fatal:true});header=JSON.parse(dec.decode(b64Bytes(parts[0])));payload=JSON.parse(dec.decode(b64Bytes(parts[1])));b64Bytes(parts[2]);}catch(error){throw Error('Header hoặc payload chưa phải JSON UTF-8 / Base64URL hợp lệ.')}if(!header||typeof header!=='object'||Array.isArray(header)||!payload||typeof payload!=='object'||Array.isArray(payload))throw Error('Header và payload phải là đối tượng JSON.');const claims=[];for(const key of ['iat','nbf','exp'])if(Object.hasOwn(payload,key)){const value=payload[key];if(typeof value!=='number'||!Number.isFinite(value)||!Number.isFinite(new Date(value*1000).getTime()))claims.push({claim:key,error:'Giá trị NumericDate chưa hợp lệ'});else claims.push({claim:key,seconds:value,utc:new Date(value*1000).toISOString(),status:key==='exp'?(now>=value?'Đã hết hạn':'Chưa hết hạn'):key==='nbf'?(now<value?'Chưa đến thời điểm hiệu lực':'Đã đến thời điểm hiệu lực'):(now<value?'Thời điểm phát hành trong tương lai':'Thời điểm phát hành')})}return {header,payload,claims,parts,summary:[`Thuật toán khai báo: ${header.alg||'Không có'}`,...claims.map(c=>c.claim+': '+(c.error||c.status)),'Chưa xác minh chữ ký. Giải mã không chứng minh token đáng tin.']}}
async function debugJwt(token,secret,verify=false){const parsed=jwt(token);let verification='Chưa xác minh chữ ký';if(verify){const hashes={HS256:'SHA-256',HS384:'SHA-384',HS512:'SHA-512'},algorithm=hashes[parsed.header.alg];if(!algorithm)throw Error('Chỉ hỗ trợ xác minh HS256, HS384 và HS512 bằng khóa bí mật. Không chấp nhận alg=none.');if(!secret)throw Error('Nhập khóa bí mật dạng UTF-8 để xác minh HMAC.');if(Object.hasOwn(parsed.header,'crit'))throw Error('Không hỗ trợ JWT có header crit.');const key=await crypto.subtle.importKey('raw',enc.encode(secret),{name:'HMAC',hash:algorithm},false,['verify']);const ok=await crypto.subtle.verify('HMAC',key,b64Bytes(parsed.parts[2]),enc.encode(parsed.parts[0]+'.'+parsed.parts[1]));verification=ok?'Chữ ký HMAC khớp với khóa đã nhập':'Chữ ký HMAC KHÔNG khớp với khóa đã nhập';}return {text:JSON.stringify({header:parsed.header,payload:parsed.payload,timeClaims:parsed.claims,signature:verification},null,2),summary:[verification,...parsed.summary.filter(s=>!s.startsWith('Chưa xác minh')),'Issuer, audience và chính sách chấp nhận token chưa được xác thực.']}}
function md5(text){const bytes=enc.encode(text),length=bytes.length,size=Math.ceil((length+9)/64)*64,buffer=new Uint8Array(size);buffer.set(bytes);buffer[length]=128;const view=new DataView(buffer.buffer);view.setUint32(size-8,(length*8)>>>0,true);view.setUint32(size-4,Math.floor(length/536870912),true);const constants=Array.from({length:64},(_,i)=>(Math.floor(Math.abs(Math.sin(i+1))*4294967296))|0),shifts=[7,12,17,22,5,9,14,20,4,11,16,23,6,10,15,21];let state=[0x67452301,0xefcdab89|0,0x98badcfe|0,0x10325476];for(let offset=0;offset<size;offset+=64){let [a,b,c,d]=state;for(let i=0;i<64;i++){let f,g;if(i<16){f=(b&c)|(~b&d);g=i}else if(i<32){f=(d&b)|(~d&c);g=(5*i+1)%16}else if(i<48){f=b^c^d;g=(3*i+5)%16}else{f=c^(b|~d);g=7*i%16}const sum=(a+f+constants[i]+view.getInt32(offset+g*4,true))|0,shift=shifts[Math.floor(i/16)*4+i%4],rotated=(sum<<shift)|(sum>>>(32-shift));[a,b,c,d]=[d,(b+rotated)|0,b,c]}state=state.map((x,i)=>(x+[a,b,c,d][i])|0)}const out=new Uint8Array(16),outView=new DataView(out.buffer);state.forEach((n,i)=>outView.setInt32(i*4,n,true));return out}
async function hashText(data){if(data.text.length>1000000)throw Error('Văn bản quá lớn; giới hạn 1 triệu ký tự.');const algorithm=data.algorithm;let bytes;if(algorithm==='MD5'){if(data.hmac)throw Error('HMAC hỗ trợ SHA-1 / SHA-256 / SHA-384 / SHA-512; hãy đổi thuật toán.');bytes=md5(data.text)}else{if(!['SHA-1','SHA-256','SHA-384','SHA-512'].includes(algorithm))throw Error('Thuật toán chưa hỗ trợ.');if(data.hmac){if(!data.key)throw Error('Nhập khóa HMAC dạng UTF-8.');const key=await crypto.subtle.importKey('raw',enc.encode(data.key),{name:'HMAC',hash:algorithm},false,['sign']);bytes=new Uint8Array(await crypto.subtle.sign('HMAC',key,enc.encode(data.text)))}else bytes=new Uint8Array(await crypto.subtle.digest(algorithm,enc.encode(data.text)))}const hex=[...bytes].map(b=>b.toString(16).padStart(2,'0')).join(''),base64=btoa(String.fromCharCode(...bytes)),text=data.encoding==='base64'?base64:hex;const summary=[`${data.hmac?'HMAC-':''}${algorithm} · ${bytes.length*8} bit · ${data.encoding==='base64'?'Base64':'Hex'}`];if(data.expected?.trim()){const expected=data.expected.trim();summary.push((data.encoding==='base64'?expected===text:expected.toLowerCase()===text)?'Kết quả KHỚP giá trị đối chiếu.':'Kết quả KHÔNG khớp giá trị đối chiếu.')}if(['MD5','SHA-1'].includes(algorithm))summary.push('MD5 / SHA-1 chỉ dành cho kiểm tra tương thích, không dùng để bảo vệ mật khẩu hoặc chống giả mạo.');return {text,summary}}
const names=['Nguyễn Minh Anh','Trần Hà An','Lê Bảo Ngọc','Phạm Gia Huy','Vũ Thu Trang','Đỗ Quang Minh'],companies=['Studio Mộc','Công ty Sao Mai','An Nhiên Labs','Green Pixel','Mây Digital'],countries=['Việt Nam','Nhật Bản','Singapore','Úc','Canada'];
