function fake(schemaText,countValue){if(schemaText.length>100000)throw Error('Schema quá lớn; giới hạn 100.000 ký tự.');const count=Number(countValue);if(!Number.isInteger(count)||count<1||count>1000)throw Error('Số bản ghi từ 1 đến 1000.');let schema;try{schema=JSON.parse(schemaText)}catch{throw Error('Schema chưa phải JSON hợp lệ.')}if(!schema||typeof schema!=='object'||Array.isArray(schema)||!Object.keys(schema).length||Object.keys(schema).length>30)throw Error('Schema phải là đối tượng JSON có 1–30 trường.');const generators=Object.entries(schema).map(([key,type])=>{if(typeof type!=='string')throw Error(`Trường ${key}: loại dữ liệu phải là chuỗi.`);const [kind,...args]=type.split(':');let fn;switch(kind){case 'id':fn=i=>i+1;break;case 'uuid':fn=()=>crypto.randomUUID();break;case 'fullName':fn=()=>pick(['Nguyễn','Trần','Lê','Phạm','Vũ','Đỗ','Hoàng','Bùi','Đặng','Hồ'])+' '+pick(['Minh','Gia','Thu','Bảo','Hà','Quang','Ngọc','Thanh'])+' '+pick(['Anh','An','Huy','Trang','Linh','Ngọc','Khánh','Phương','Dương','Nam']);break;case 'email':fn=i=>'user'+(i+1)+'@example.com';break;case 'company':fn=()=>pick(companies);break;case 'country':fn=()=>pick(countries);break;case 'boolean':fn=()=>Math.random()<.5;break;case 'date':fn=()=>new Date(Date.UTC(2024,0,1)+Number(ToolHubRandomTime.numbers({min:0,max:1095,count:1,decimals:0,unique:false}).values[0])*86400000).toISOString();break;case 'integer':case 'number':{const options={min:args[0]||'0',max:args[1]||'100',decimals:kind==='integer'?0:Number(args[2]||2),count:1,unique:false};ToolHubRandomTime.numbers(options);fn=()=>Number(ToolHubRandomTime.numbers(options).values[0]);break}case 'pick':if(args.length!==1||!args[0])throw Error('Dùng pick:giá trị A|giá trị B');fn=()=>pick(args[0].split('|'));break;case 'literal':fn=()=>args.join(':');break;default:throw Error(`Loại “${kind}” của trường ${key} chưa hỗ trợ.`)}return [key,fn]});const rows=Array.from({length:count},(_,i)=>{const row=Object.create(null);for(const [key,fn] of generators)row[key]=fn(i);return row});return {text:JSON.stringify(rows,null,2),summary:[`${count} bản ghi · ${generators.length} trường · JSON array`,'Dữ liệu tổng hợp để thử nghiệm; email dùng miền example.com. Tên có thể trùng tên thực.']}}
